/**
 * Registers the Workbox service worker (generated by vite-plugin-pwa).
 *
 * Updates never reload the page while someone is using it (that could throw
 * away a receipt being reviewed). A new version waits and is applied the next time
 * the app goes to the background on a screen with nothing unsaved.
 */
export function registerServiceWorker() {
  if (!('serviceWorker' in navigator) || import.meta.env.DEV) return;
  window.addEventListener('load', () => {
    import('virtual:pwa-register')
      .then(({ registerSW }) => {
        let pending = false;
        const updateSW = registerSW({
          immediate: true,
          onNeedRefresh() {
            pending = true;
          },
          onRegisteredSW(_url, reg) {
            // Home Screen apps can stay open for days: look for updates hourly.
            if (reg) setInterval(() => void reg.update().catch(() => {}), 60 * 60 * 1000);
          },
        });
        document.addEventListener('visibilitychange', () => {
          const editing = /^#\/(edit|review|scan)/.test(location.hash);
          if (document.visibilityState === 'hidden' && pending && !editing) void updateSW(true);
        });
      })
      .catch(() => {
        /* offline support is a bonus, never a blocker */
      });
  });
}
